import re
import six
import logging

from ute_common_util.timeout import Timeout
from SSHLibrary import SSHClient

from .exception import BTSSMExecutionError
from .checker import ErrorChecker


class Executor(object):
    """A class responsible for executing operations on the client and for reacting properly to the received data."""

    BTSSM_KILL_CMD = [
        "sudo pkill -f com.nokia.em.poseidon.PoseidonStarter",
        "sudo pkill -f com.nokia.em.sitemgr.SitemgrStarter",
    ]

    KILL_JAVA_CMD = "sudo pkill -9 -f 'com.nokia.em.bts.coreasset.application.CoreAssetToolApplication'"
    LOG_FILES = ['ToolLog.xml', 'PoseidonLog.xml']

    def __init__(self, ssh_conn_params, ssh_login_params, log_path, timeout, rc_only=False):
        """
        :param BtssmConfig config: the BTS SM configuration
        """
        self._client = None
        self._ssh_conn_params = ssh_conn_params
        self._ssh_login_params = ssh_login_params
        self._log = logging.getLogger(__name__)
        self._log_path = log_path
        self._timeout = timeout
        self._finished_regexp = re.compile("Finished with RC: \d+")
        self._rc_only = rc_only

    def connect(self):
        """Connects the underlying client."""
        self._client = SSHClient(timeout=self._timeout, **self._ssh_conn_params)
        if "look_for_keys" in six.get_function_code(self._client.login).co_varnames:
            self._client.login(look_for_keys=True, **self._ssh_login_params)
        else:
            self._client.login(**self._ssh_login_params)

    def disconnect(self):
        """Disconnects the underlying client."""
        self._client.close()

    def file_exists(self, path):
        """Checks if file exists on remote host.

        :param string path: Path to file on remote host.

        :return: True if file exists.
        :rtype: boolean
        """
        out_err_rc = self._client.execute_command('ls "{}"'.format(path))
        rc = out_err_rc[2]
        return True if rc == 0 else False

    def rename(self, old, new):
        """Renames the file or directory
        :param string old: Actual name of the file or directory.
        :param string new: New name of the file or directory.
        """
        self._client.execute_command('mv "{}" "{}"'.format(old, new))

    def get_file(self, remote_src, local_dest):
        """Download a file from client.

        :return: The path to downloaded file.
        :rtype: string
        """
        return self._unify_put_get_file_output(self._client.get_file(remote_src, local_dest))[0][1]

    def put_file(self, local_src, remote_dest):
        """Upload a file to client.

        :return: The path to uploaded file.
        :rtype: string
        """
        return self._unify_put_get_file_output(self._client.put_file(local_src, remote_dest))[0][1]

    def run(self, cmd, **kwargs):
        """Execute the provided command on the client using the standard command execution channel.

        :param string cmd: Command to execute.

        Available kwarg value(s) for run:
        timeout - execution timeout for execute_command

        :return: Received output (stdout only).
        :rtype: string

        :raises: BTSSMExecutionError if the executed command finishes with a code different than 0.
        """
        timeout = kwargs.get('timeout')
        out, err, rc = self._client.execute_command(cmd, timeout=timeout if timeout else None)
        if rc == 0:
            return out
        raise BTSSMExecutionError("Error found after executing command ({})".format(cmd), out + '\n' + err, str(rc))

    def run_ignoring_rc(self, cmd):
        """Execute the provided command on the client using the standard command execution channel and ignore the return code.

        :param string cmd: Command to execute.

        :return: Received output (stdout only).
        :rtype: string
        """
        output = self._client.execute_command(cmd)
        self._log.debug("Command: {}\nIgnored RC: {}".format(cmd, output))
        return output[0]

    def run_via_shell(self, cmd, op):
        """Execute the provided command on the client by writing the command to the shell.

        :param string cmd: Command to execute.

        :return: Received data.
        :rtype: string

        :raises: BTSSMExecutionError if the executed command finishes with a code different than 0.
        """
        self._clean_old_logs()
        self._write_to_shell(cmd)
        out = self._wait_until_finish()
        rc = self._find_return_code(out)
        if rc == '0':
            ErrorChecker(op).check(out)
            return out
        raise BTSSMExecutionError("Error found after executing command ({})".format(cmd), out, rc, rc_only=self._rc_only)

    def _kill_btssm(self, client):
        for each in Executor.BTSSM_KILL_CMD:
            client.execute_command(each)

    def _write_to_shell(self, cmd):
        self._client.write('cd "{}"\n{}\necho "Finished with RC: $?"\n'.format(self._log_path, cmd))

    def _wait_until_finish(self):
        out = buf = ''
        timeout = Timeout(self._timeout)
        while timeout.is_not_reached():
            out, buf = self._read_from_shell(out, buf)
            if self._finished_regexp.search(out):
                return out
        raise BTSSMExecutionError("Execution timeout ({} seconds) was exceeded.".format(self._timeout))

    def _find_return_code(self, out):
        rcs = re.search("Finished with RC: (\d+)", out.strip())
        if rcs:
            return rcs.groups()[0]

    def _close_java_app(self):
        self._client.execute_command(Executor.KILL_JAVA_CMD)

    def _clean_old_logs(self):
        for each in Executor.LOG_FILES:
            self._client.execute_command('rm -rf "{}/{}"'.format(self._log_path, each))

    def _unify_put_get_file_output(self, ssh_result):
        return zip(*ssh_result) if type(ssh_result) is tuple else ssh_result

    def _read_from_shell(self, out, buf):
        buf += self._client.read()
        if '\n' in buf:
            self._print_lines(buf)
            out += buf
            buf = ''
        return out, buf

    def _print_lines(self, buf):
        for line in buf.split('\n'):
            if line.strip():
                self._log.debug(line)
